use kimo_core::color::cdl_xml::Collection;
const CC:&str=r#"<ColorCorrection id="shot&amp;1"><Description>A &amp; B</Description><InputDescription>ACEScct</InputDescription><SOPNode><Description>SOP</Description><Slope>1.02 0.98 1</Slope><Offset>0.01 -0.005 0</Offset><Power>1.04 1 0.98</Power></SOPNode><SatNode><Description>SAT</Description><Saturation>0.95</Saturation></SatNode></ColorCorrection>"#;
#[test]fn semantic_roundtrip(){let c=Collection::parse(CC).unwrap();for single in [true,false]{let xml=c.xml(single).unwrap();assert_eq!(Collection::parse(&xml).unwrap(),c);}let list=format!("<ColorDecisionList><ColorDecision>{CC}</ColorDecision><ColorDecision>{}</ColorDecision></ColorDecisionList>",CC.replace("shot&amp;1","shot2"));let c=Collection::parse(&list).unwrap();assert!(c.select(None).is_err());assert_eq!(c.select(Some("shot2")).unwrap().id,"shot2");assert_eq!(Collection::parse(&c.xml(false).unwrap()).unwrap(),c);}
#[test]fn strict_rejection(){for s in [CC.replace("<Slope>","<Slope huh=\"x\">"),CC.replace("0.95","NaN"),CC.replace("<Power>1.04 1 0.98</Power>","<Power>0 1 1</Power>"),CC.replace("<SatNode>","<Bad/><SatNode>"),format!("<!DOCTYPE x>{CC}"),CC.replace("<Slope>1.02 0.98 1</Slope>","<Slope>1 1 1</Slope><Slope>1 1 1</Slope>"),format!("<ColorDecisionList><ColorDecision>{CC}{CC}</ColorDecision></ColorDecisionList>")]{assert!(Collection::parse(&s).is_err(),"{s}");}}
#[cfg(feature="native-ocio")]
#[test]fn native_asc_formula_hash_repeat(){use kimo_core::{effects::Frame,color::ocio_config::Processor};let c=Collection::parse(CC).unwrap();let p=Processor::cdl(&c.corrections[0]).unwrap();let input=[-0.1f32,0.18,2.,0.5,0.2,0.4,0.7,1.];let mut f=Frame{w:2,h:1,d:input.to_vec()};p.apply(&mut f).unwrap();let out=f.d.clone();let c=&c.corrections[0];for i in 0..2{let a=[0,1,2].map(|j|((input[i*4+j] as f64*c.slope[j]+c.offset[j]).clamp(0.,1.)).powf(c.power[j]));let y=0.2126*a[0]+0.7152*a[1]+0.0722*a[2];for j in 0..3{let v=(y+c.saturation*(a[j]-y)).clamp(0.,1.);assert!((f.d[i*4+j] as f64-v).abs()<2e-6);}assert_eq!(f.d[i*4+3],input[i*4+3]);}for _ in 0..16{let mut f=Frame{w:2,h:1,d:input.to_vec()};p.apply(&mut f).unwrap();assert_eq!(f.d,out);}}
#[cfg(feature="native-ocio")]
#[test]fn apply_export_immutable_payload(){use kimo_core::commands::{Session,dispatch};use serde_json::json;let mut s=Session::new();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let id=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","color":[0.18,0.18,0.18],"start":0,"duration":1})).unwrap()["clip_id"].clone();let path=format!("/tmp/cdl-in-{}.cc",std::process::id());std::fs::write(&path,CC).unwrap();let e=dispatch(&mut s,"apply_asc_cdl",&json!({"clip_id":id,"path":path,"encoding":"current"})).unwrap()["effect_id"].clone();std::fs::remove_file(&path).unwrap();let out=format!("/tmp/cdl-out-{}.cc",std::process::id());dispatch(&mut s,"export_asc_cdl",&json!({"clip_id":id,"effect_id":e,"path":out})).unwrap();assert_eq!(Collection::read(&out).unwrap(),Collection::parse(CC).unwrap());assert!(kimo_core::render::render_frame(&s.project,0.4,&s.cache).is_ok());}
